import{_ as a,c as t,o as i,ag as s}from"./chunks/framework.B-XtCDNB.js";const u=JSON.parse('{"title":"2.5. Operators","description":"2.5. Operators Assignment (=) = Assignment. The left operand must be an identifier, and the right must result in a value or reference as appropriate. Basic arithmetic (+, -, /, *, %) +, -, /, *, %...","frontmatter":{},"headers":[],"relativePath":"tutorials/programming-language/main/02-00-basics/02-05-operators.md","filePath":"tutorials/programming-language/main/02-00-basics/02-05-operators.md","lastUpdated":1784474597000}'),o={name:"tutorials/programming-language/main/02-00-basics/02-05-operators.md"};function n(l,e,d,r,h,c){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="_2-5-operators" tabindex="-1">2.5. Operators <a class="header-anchor" href="#_2-5-operators" aria-label="Permalink to &quot;2.5. Operators&quot;">​</a></h1><h2 id="assignment" tabindex="-1">Assignment (<code>=</code>) <a class="header-anchor" href="#assignment" aria-label="Permalink to &quot;Assignment (`=`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span></code></pre></div><p>Assignment. The left operand must be an identifier, and the right must result in a value or reference as appropriate.</p><h2 id="basic-arithmetic" tabindex="-1">Basic arithmetic (<code>+</code>, <code>-</code>, <code>/</code>, <code>*</code>, <code>%</code>) <a class="header-anchor" href="#basic-arithmetic" aria-label="Permalink to &quot;Basic arithmetic (`+`, `-`, `/`, `*`, `%`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+, -, /, *, %</span></span></code></pre></div><p>Basic arithmetic, applied to left and right operands. The <code>+</code> operator can also concatenate strings.</p><h2 id="compound-assignment-arithmetic" tabindex="-1">Compound assignment (arithmetic) <a class="header-anchor" href="#compound-assignment-arithmetic" aria-label="Permalink to &quot;Compound assignment (arithmetic)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+=, -=, /=, *=, %=</span></span></code></pre></div><p>Arithmetic operation between left and right operands, where the left must be an identifier, to which the result is assigned.</p><h2 id="increment-and-decrement" tabindex="-1">Increment and decrement (<code>++</code>, <code>--</code>) <a class="header-anchor" href="#increment-and-decrement" aria-label="Permalink to &quot;Increment and decrement (`++`, `--`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">++, --</span></span></code></pre></div><p>Increment and decrement operations with implicit assignment. These take just one argument, which must be an identifier of a simple data type. The value will be changed and assigned back to the identifier. These operators may be placed in either prefix or postfix positions - with the former the evaluated value of the statement will be the newly calculated value, with the latter the original value is returned.</p><h2 id="bitwise-operators" tabindex="-1">Bitwise operators <a class="header-anchor" href="#bitwise-operators" aria-label="Permalink to &quot;Bitwise operators&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|, ^, &amp;, ~, |=, &amp;=, ^=</span></span></code></pre></div><p>Bitwise operations: or, exclusive or, and, not. The second set include assignment and are analogous to the arithmetic versions. These can be applied to any of the simple value types. (There is no assignment operator associated with <code>~</code> because this is a unary operator. The equivalent operation is just <code>a = ~a</code>).</p><h2 id="bit-shift" tabindex="-1">Bit shift (<code>&lt;&lt;</code>, <code>&gt;&gt;</code>) <a class="header-anchor" href="#bit-shift" aria-label="Permalink to &quot;Bit shift (`&lt;&lt;`, `&gt;&gt;`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;&lt;, &gt;&gt;</span></span></code></pre></div><p>Bit shift operations, shifting the left operand a number of bits according the right operand.</p><h2 id="compound-assignment-bit-shift" tabindex="-1">Compound assignment (bit shift) <a class="header-anchor" href="#compound-assignment-bit-shift" aria-label="Permalink to &quot;Compound assignment (bit shift)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;&lt;=, &gt;&gt;=</span></span></code></pre></div><p>Bit shift operations, shifting the left operand a number of bits according the right operand. The left operand must be an identifier, to which the result is assigned.</p><h2 id="equality" tabindex="-1">Equality (<code>==</code>) <a class="header-anchor" href="#equality" aria-label="Permalink to &quot;Equality (`==`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">==</span></span></code></pre></div><p>Equality test. Evaluates to a <code>bool</code> value dependent on whether the left and right operands are equal. In the case of value types this means their values are equal, in the case of reference types that the objects are the same instance. An exception to this rule is the <code>string</code> type, which is tested for equality by value.</p><h2 id="relational-and-inequality" tabindex="-1">Relational and inequality (<code>&lt;</code>, <code>&gt;</code>, <code>&gt;=</code>, <code>&lt;=</code>, <code>!=</code>) <a class="header-anchor" href="#relational-and-inequality" aria-label="Permalink to &quot;Relational and inequality (`&lt;`, `&gt;`, `&gt;=`, `&lt;=`, `!=`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;, &gt;, &gt;=, &lt;=, !=</span></span></code></pre></div><p>Inequality tests. Evaluate to a <code>bool</code> value dependent on whether the left and right operands are different in the manner described. These are valid for simple value data types, and the <code>string</code> type. For strings these operators compare the lexicographical order.</p><h2 id="logical-operators" tabindex="-1">Logical operators (<code>!</code>, <code>&amp;&amp;</code>, <code>||</code>) <a class="header-anchor" href="#logical-operators" aria-label="Permalink to &quot;Logical operators (`!`, `&amp;&amp;`, `||`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">!, &amp;&amp;, ||</span></span></code></pre></div><p>Logic operations: not, and, or. These operations can be applied to Boolean values - the first taking just one value the others two.</p><h2 id="ternary-conditional" tabindex="-1">Ternary conditional (<code>?</code> <code>:</code>) <a class="header-anchor" href="#ternary-conditional" aria-label="Permalink to &quot;Ternary conditional (`?` `:`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">? :</span></span></code></pre></div><p>Ternary conditional operator. Evaluates a condition and returns either the value of the left or the right sub-expression based on whether the condition is true or false: <code>condition ? value_if_true : value_if_false</code></p><h2 id="null-coalescing" tabindex="-1">Null coalescing (<code>??</code>) <a class="header-anchor" href="#null-coalescing" aria-label="Permalink to &quot;Null coalescing (`??`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">??</span></span></code></pre></div><p>Null coalescing operator: <code>a ?? b</code> is equivalent to <code>a != null ? a : b</code>. This operator is useful for example to provide a default value in case a reference is <code>null</code>:</p><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stdout.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello, %s!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, name ?? </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;unknown person&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="null-conditional" tabindex="-1">Null-conditional (<code>?.</code>, <code>?[]</code>) <a class="header-anchor" href="#null-conditional" aria-label="Permalink to &quot;Null-conditional (`?.`, `?[]`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">?., ?[]</span></span></code></pre></div><p>Null-conditional (“safe navigation”) operators. If the expression to the left of <code>?.</code> is <code>null</code>, the member access or method call is skipped and the whole expression evaluates to <code>null</code>; otherwise it behaves like a normal <code>.</code> access. For example, <code>widget?.destroy ()</code> calls <code>destroy ()</code> only when <code>widget</code> is not <code>null</code>. A <code>void</code> method invoked this way is simply skipped when the receiver is <code>null</code>. The <code>?[]</code> form does the same for element access (and slice expressions use a related <code>?[ … ]</code> syntax).</p><h2 id="non-null-assertion" tabindex="-1">Non-null assertion (<code>(!)</code>) <a class="header-anchor" href="#non-null-assertion" aria-label="Permalink to &quot;Non-null assertion (`(!)`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(!)</span></span></code></pre></div><p>Non-null assertion (explicit non-null cast). This unary operator tells the compiler to treat a nullable expression as non-null, which is needed in some situations such as assigning a nullable reference to a non-nullable variable when you know the value is not <code>null</code>:</p><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o1 = (!) o2;</span></span></code></pre></div><p>It is used most often together with strict non-null checking; see <a href="./../05-00-experimental-features/05-03-strict-non-null-mode.html">5.3. Strict Non-Null Mode</a>.</p><h2 id="membership-in" tabindex="-1">Membership (<code>in</code>) <a class="header-anchor" href="#membership-in" aria-label="Permalink to &quot;Membership (`in`)&quot;">​</a></h2><div class="language-vala vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vala</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span></span></code></pre></div><p>Checks if the right operand contains the left operand. This operator works on arrays, strings, collections or any other type that has an appropriate <code>contains ()</code> method. For strings, it performs a substring search.</p><h2 id="operator-overloading" tabindex="-1">Operator overloading <a class="header-anchor" href="#operator-overloading" aria-label="Permalink to &quot;Operator overloading&quot;">​</a></h2><p>Operators cannot be overloaded in Vala. There are extra operators that are valid in the context of lambda declarations and other specific tasks - these are explained in the context they are applicable.</p>',51)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
